import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.DQbZ8cc1.js";const c=JSON.parse('{"title":"Docker Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/installation/docker.md","filePath":"en/docs/installation/docker.md"}'),n={name:"en/docs/installation/docker.md"};function l(o,s,p,d,h,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="docker-deployment" tabindex="-1">Docker Deployment <a class="header-anchor" href="#docker-deployment" aria-label="Permalink to “Docker Deployment”">​</a></h1><h2 id="option-1-built-in-mysql" tabindex="-1">Option 1: Built-in MySQL <a class="header-anchor" href="#option-1-built-in-mysql" aria-label="Permalink to “Option 1: Built-in MySQL”">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>After startup, open <code>http://localhost:3000</code> and complete the installation wizard.</p><p>The default <code>docker-compose.yml</code> includes MySQL. In this mode, database fields in the installer are locked, and the system automatically uses the MySQL service inside Docker:</p><ul><li>Host: <code>mysql</code></li><li>Port: <code>3306</code></li><li>Database: <code>bbsgo</code></li><li>Username: <code>bbsgo</code></li></ul><p>The default <code>docker-compose.yml</code> starts two services:</p><ul><li><code>mysql</code>: MySQL 8.4, persisted in the Docker volume <code>mysql-data</code></li><li><code>bbs-go</code>: the application service. A single image runs both the Go API and React Router SSR. The API listens on <code>8082</code> inside the container, and the Web SSR service listens on and exposes <code>3000</code></li></ul><h2 id="option-2-single-container" tabindex="-1">Option 2: Single Container <a class="header-anchor" href="#option-2-single-container" aria-label="Permalink to “Option 2: Single Container”">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BBSGO_ENV=prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NODE_ENV=production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PORT=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BBSGO_SERVER_URL=http://127.0.0.1:8082</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TZ=Asia/Shanghai</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go-data:/app/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go-logs:/app/logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go-uploads:/app/res/uploads</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  bbs-go:latest</span></span></code></pre></div><p>After startup, open <code>http://localhost:3000</code>. In the installer, enter an external MySQL configuration manually or choose SQLite. This mode does not orchestrate a MySQL service, so no additional compose file is required.</p><h2 id="persistent-data" tabindex="-1">Persistent Data <a class="header-anchor" href="#persistent-data" aria-label="Permalink to “Persistent Data”">​</a></h2><p>For both modes, persist these paths:</p><ul><li><code>/app/data</code>: config file, SQLite database, search indexes, and runtime data</li><li><code>/app/logs</code>: service logs</li><li><code>/app/res/uploads</code>: uploaded files and auto-downloaded IP databases</li></ul><p>The built-in MySQL mode also persists:</p><ul><li><code>/var/lib/mysql</code>: MySQL data</li></ul><p>The image includes a default config file. On first startup, it is copied automatically to <code>/app/data/bbs-go.yaml</code>. <code>/app/bbs-go.yaml</code> in the container working directory points to this persisted config file, so the application still reads <code>bbs-go.yaml</code> from its startup directory as usual. The installer writes back values such as <code>installed</code> and site settings. In single-container mode, it also writes the database settings entered by the user.</p><h2 id="change-default-passwords" tabindex="-1">Change Default Passwords <a class="header-anchor" href="#change-default-passwords" aria-label="Permalink to “Change Default Passwords”">​</a></h2><p>Before production deployment, change the built-in MySQL passwords with environment variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BBSGO_DOCKER_MYSQL_ROOT_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_root_password</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BBSGO_DOCKER_MYSQL_PASSWORD=your_password </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>You may also set:</p><ul><li><code>BBSGO_DOCKER_MYSQL_DATABASE</code>: database name, default <code>bbsgo</code></li><li><code>BBSGO_DOCKER_MYSQL_USER</code>: database username, default <code>bbsgo</code></li><li><code>BBSGO_DOCKER_MYSQL_PASSWORD</code>: database password, default <code>bbsgo_password</code></li><li><code>BBSGO_DOCKER_MYSQL_ROOT_PASSWORD</code>: root password, default <code>bbsgo_root_password</code></li></ul><p>In built-in MySQL mode, the backend builds the database connection from these environment variables automatically. You do not need to edit <code>db.url</code> in <code>/app/data/bbs-go.yaml</code>.</p><h2 id="common-commands" tabindex="-1">Common Commands <a class="header-anchor" href="#common-commands" aria-label="Permalink to “Common Commands”">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbs-go</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span></code></pre></div><p>To remove database and upload volumes together:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="github-actions-to-docker-hub" tabindex="-1">GitHub Actions to Docker Hub <a class="header-anchor" href="#github-actions-to-docker-hub" aria-label="Permalink to “GitHub Actions to Docker Hub”">​</a></h2><p>The project provides <code>.github/workflows/docker-image.yml</code>. It builds and pushes images on <code>main</code> / <code>master</code>, <code>v*</code> tags, and manual workflow runs. Pull requests build only and do not push.</p><p>Configure these in the GitHub repository:</p><ul><li>Repository variable: <code>DOCKERHUB_REPOSITORY</code>, for example <code>yourname/bbs-go-pro</code></li><li>Repository secret: <code>DOCKERHUB_USERNAME</code></li><li>Repository secret: <code>DOCKERHUB_TOKEN</code></li></ul><p>Tag rules:</p><ul><li>Default branch pushes <code>latest</code>, branch name, and <code>sha-&lt;commit&gt;</code> tags</li><li><code>v*</code> Git tags push the version tag and <code>sha-&lt;commit&gt;</code> tag</li><li>Image platform: <code>linux/amd64</code></li></ul>`,33)])])}const F=i(n,[["render",l]]);export{c as __pageData,F as default};
